/**
 * CyberShield AI — UnifiedThreatReport Schema
 * =============================================
 * Canonical schema for all threat reports generated by CyberShield AI.
 *
 * Design principles:
 *   1. Only stable, analytical fields are included — no mutable UI state.
 *   2. All string enums use lowercase snake_case for cross-language stability.
 *   3. Arrays are always sorted before hashing to ensure determinism.
 *   4. Timestamps use ISO 8601 UTC format (e.g. "2026-11-07T17:00:00.000Z").
 *   5. Numeric confidence scores are normalized to 0–100 integers.
 *
 * This schema is shared between:
 *   - Next.js API route  (app/api/blockchain/route.ts)
 *   - Python hashing     (CyberShield-Blockchain/python/report_hash.py)
 *   - Solidity contract  (contracts/ThreatReportRegistry.sol)
 *
 * Member 1 (Backend) → produces this shape.
 * Member 3 (Blockchain) → hashes and registers it.
 */

// ─────────────────────────────────────────────────────────────────
//  Enum literals
// ─────────────────────────────────────────────────────────────────

export type ThreatSeverity =
  | "critical"   // Immediate action required. Active exploit / data breach.
  | "high"       // Strong evidence of malicious activity.
  | "medium"     // Suspicious patterns, needs investigation.
  | "low"        // Anomaly detected, low risk.
  | "info";      // Informational finding, no immediate threat.

export type ThreatCategory =
  | "malware"
  | "phishing"
  | "ransomware"
  | "ddos"
  | "data_exfiltration"
  | "insider_threat"
  | "brute_force"
  | "sql_injection"
  | "xss"
  | "zero_day"
  | "social_engineering"
  | "supply_chain"
  | "credential_theft"
  | "network_intrusion"
  | "other";

export type ThreatStatus =
  | "detected"      // Threat identified, not yet acted upon.
  | "investigating" // Under active review.
  | "contained"     // Spread stopped, root cause under review.
  | "remediated"    // Fully resolved.
  | "false_positive"; // Closed as non-threat.

// ─────────────────────────────────────────────────────────────────
//  Sub-structures
// ─────────────────────────────────────────────────────────────────

export interface AffectedAsset {
  /** Asset type: "host" | "domain" | "ip" | "user" | "service" | "file" */
  asset_type: string;
  /** Identifier — hostname, domain, service name. No raw IP or PII. */
  identifier: string;
}

export interface Indicator {
  /** IOC type: "hash" | "domain" | "url" | "cve" | "signature" | "pattern" */
  ioc_type: string;
  /** The indicator value — file hash, CVE ID, domain, etc. Never raw IP. */
  value: string;
}

export interface RemediationStep {
  /** Priority order (1 = highest) */
  priority: number;
  /** Short imperative action description */
  action: string;
}

// ─────────────────────────────────────────────────────────────────
//  UnifiedThreatReport — the canonical report shape
// ─────────────────────────────────────────────────────────────────

export interface UnifiedThreatReport {
  /**
   * Unique report identifier assigned by Member 1's backend.
   * Format: "CSR-<YYYYMMDD>-<SEQUENCE>" e.g. "CSR-20261107-00042"
   */
  report_id: string;

  /** Schema version — increment when adding/removing fields */
  schema_version: "1.0";

  /** ISO 8601 UTC timestamp when the threat was first detected */
  detected_at: string;

  /** ISO 8601 UTC timestamp when this report was generated */
  generated_at: string;

  // ── Threat classification ───────────────────────────────────────

  severity:  ThreatSeverity;
  category:  ThreatCategory;
  status:    ThreatStatus;

  /**
   * AI confidence in this classification (0–100).
   * 0 = uncertain, 100 = certain.
   */
  confidence_score: number;

  // ── Textual summary ─────────────────────────────────────────────

  /** One-sentence summary of the threat for executive dashboards */
  summary: string;

  /** Detailed technical description of the attack vector and behavior */
  description: string;

  // ── Evidence ────────────────────────────────────────────────────

  /**
   * Indicators of Compromise.
   * Sorted by ioc_type then value before hashing.
   * Never include raw IP addresses — use anonymized hashes or domains.
   */
  indicators: Indicator[];

  /**
   * Assets confirmed or suspected to be affected.
   * Sorted by asset_type then identifier before hashing.
   */
  affected_assets: AffectedAsset[];

  // ── Remediation ─────────────────────────────────────────────────

  /**
   * Ordered remediation steps (sorted by priority before hashing).
   */
  remediation_steps: RemediationStep[];

  // ── Attribution ─────────────────────────────────────────────────

  /**
   * Optional MITRE ATT&CK technique IDs (e.g. ["T1566", "T1078"]).
   * Sorted before hashing.
   */
  mitre_techniques: string[];

  /**
   * Optional threat actor or campaign name.
   * Use "" if unknown.
   */
  threat_actor: string;
}

// ─────────────────────────────────────────────────────────────────
//  Normalizer — strips any extra fields, enforces field order
//  and sorts all arrays before hashing.
// ─────────────────────────────────────────────────────────────────

type RawRecord = Record<string, unknown>;

export function normalizeThreatReport(raw: RawRecord): RawRecord {
  const indicators: RawRecord[] = ((raw.indicators as RawRecord[]) ?? [])
    .map((ioc) => ({
      ioc_type: String(ioc.ioc_type ?? ""),
      value:    String(ioc.value    ?? ""),
    }))
    .sort((a, b) =>
      (a.ioc_type as string).localeCompare(b.ioc_type as string) ||
      (a.value    as string).localeCompare(b.value    as string)
    );

  const affected_assets: RawRecord[] = ((raw.affected_assets as RawRecord[]) ?? [])
    .map((a) => ({
      asset_type: String(a.asset_type ?? ""),
      identifier: String(a.identifier ?? ""),
    }))
    .sort((a, b) =>
      (a.asset_type as string).localeCompare(b.asset_type as string) ||
      (a.identifier as string).localeCompare(b.identifier as string)
    );

  const remediation_steps: RawRecord[] = ((raw.remediation_steps as RawRecord[]) ?? [])
    .map((s) => ({
      priority: Number(s.priority ?? 0),
      action:   String(s.action   ?? ""),
    }))
    .sort((a, b) => (a.priority as number) - (b.priority as number));

  const mitre_techniques: string[] = ([
    ...((raw.mitre_techniques as string[]) ?? []),
  ]).sort();

  return {
    report_id:        String(raw.report_id        ?? ""),
    schema_version:   "1.0",
    detected_at:      String(raw.detected_at      ?? ""),
    generated_at:     String(raw.generated_at     ?? ""),
    severity:         String(raw.severity         ?? ""),
    category:         String(raw.category         ?? ""),
    status:           String(raw.status           ?? ""),
    confidence_score: Number(raw.confidence_score ?? 0),
    summary:          String(raw.summary          ?? ""),
    description:      String(raw.description      ?? ""),
    indicators,
    affected_assets,
    remediation_steps,
    mitre_techniques,
    threat_actor:     String(raw.threat_actor     ?? ""),
  };
}
